import os, sys; sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from common import Bank
B = Bank('127.', 1208, own='cte_131.jsonl')
def H(code, d, q, right, wrong, e): return B.hand(code, d, q, right, wrong, e)
H("880.d.5.A",3,"Before pulling a crease in a quarter panel, Marcus grinds the paint off a four-inch band around the damage with a 36-grit disc. He is:","removing paint from the damaged area of a body panel",["adding paint","only washing the panel","masking the panel"],"Strip the damaged area.")
H("880.d.5.A",4,"A coating-removal step before metal work is mainly done to:","expose bare metal so the damage can be read and the repair bonds well",["add weight","make the panel look shiny","use up abrasives"],"Bare metal shows damage.")
H("880.d.5.B",3,"After rough-shaping a fender, Priya drags her palm over it and sights along it with a bright light to find waves. She is:","identifying and repairing surface irregularities on a damaged body panel",["painting the fender","ignoring waves","adding primer"],"Check the contour.")
H("880.d.5.B",4,"A low spot is usually found with:","a flexible file or hand feel and then corrected before filler",["a paint gun","a wrench","a tire gauge"],"Locate lows first.")
H("880.d.5.C",3,"Using a spoon dolly behind a door skin, Jess taps the ridge around a dent and then lightly planishes the center. She is demonstrating:","hammer and dolly techniques for dent repair",["welding","spraying","masking"],"Dolly work.")
H("880.d.5.C",4,"With the hammer off-dolly, the technician is striking:","the high area beside the dolly to lower it without stretching",["the center of the dolly","the glass","the primer"],"Off-dolly lowers highs.")
H("880.d.5.D",3,"A technician heats a small oil-canned spot on a hood to dull cherry red and quenches it with a damp rag to tighten the metal. She is performing:","heat shrinking of a stretched panel area",["cold shrinking","painting","polishing"],"Heat then cool.")
H("880.d.5.D",4,"When heat shrinking, the technician must watch the heat to avoid:","burning or warping the surrounding panel",["cooling the panel","cleaning the panel","painting the panel"],"Control the heat.")
H("880.d.5.E",3,"Instead of using a torch, Dani works a stretched section with a hammer and dolly in a pattern so the metal tightens. She is performing:","cold shrinking of a stretched panel area",["heat shrinking","welding","masking"],"Hammer shrinking.")
H("880.d.5.E",4,"Compared with heat shrinking, cold shrinking is often favored on panels because it:","avoids the paint and metal damage heat can cause",["is much hotter","uses more fuel","needs no tools"],"No heat risk.")
H("880.d.5.F",3,"A student scuffs a repaired area, cleans it, mixes filler and cream hardener to a uniform color and spreads a thin coat. She is:","identifying, preparing and applying body filler",["mixing paint","sanding primer","polishing clear"],"Filler steps.")
H("880.d.5.F",4,"Filler should be spread in thin layers because thick layers can:","crack, shrink or fail to cure properly",["improve strength","cure instantly","stick better"],"Thin coats.")
H("880.d.5.G",3,"After curing, Omar shapes the filler with 80-grit on a long block, then moves to 180 and 240 before primer. He is:","rough sanding and finish sanding body filler for primer",["washing the filler","stripping the filler","painting the filler"],"Progressive grits.")
H("880.d.5.G",4,"A long sanding block is used on large panels to:","keep the contour flat and avoid waves",["add waves","dry the filler","save paper"],"Block sanding.")
H("880.d.5.H",3,"A technician learns that aluminum should be worked with dedicated tools, kept away from steel dust and shaped with care because it work-hardens. She is determining:","the proper metal finishing techniques for aluminum",["the proper paint color","the tire pressure","the oil change"],"Aluminum technique.")
H("880.d.5.H",4,"Using steel abrasives on aluminum after grinding steel can lead to:","galvanic corrosion from embedded steel particles",["faster drying","stronger metal","shinier metal"],"Avoid cross-contamination.")
H("880.d.5.I",3,"A technician checks the manufacturer's guidance for filler on an aluminum fender, then uses a filler approved for aluminum. She is determining:","the proper application of body filler to aluminum",["no filler is allowed ever","any filler works","paint only"],"Use the approved filler.")
H("880.d.5.I",4,"Before applying filler to aluminum, the surface should be:","cleaned and mechanically prepared with aluminum-safe abrasives",["left oily","coated with water","painted red"],"Clean and prep.")
H("880.d.6.A",3,"A customer's driver window won't go up. The technician checks the switch, the motor and the regulator inside the door. She is:","inspecting, adjusting, repairing or replacing window systems",["washing the door","painting the window","ignoring the problem"],"Window system.")
H("880.d.6.A",4,"A window that makes a grinding noise and moves crookedly in its track likely has a:","damaged or off-track regulator",["new tire","full tank","clean filter"],"Regulator failure.")
H("880.d.6.B",3,"A technician replaces a torn door weatherstrip and checks that the seal makes even contact all around. She is:","inspecting, adjusting, removing and reinstalling body sealing systems such as weatherstripping",["painting the door","ignoring leaks","guessing"],"Sealing systems.")
H("880.d.6.B",4,"A door seal that has lost its resilience is likely to cause:","wind noise and water leaks",["quiet cabins","dry carpets","less wear"],"Seals keep out wind and water.")
H("880.d.6.C",3,"A technician inspects the run channels and the glass of a door and finds the felt strips worn so the glass rattles. She is:","inspecting, adjusting, repairing or replacing run channels and glass related to door window operation",["painting","guessing","avoiding repair"],"Run channels.")
H("880.d.6.C",4,"Worn glass run channels can cause:","glass that rattles, binds or doesn't seal",["better fit","quieter doors","faster windows"],"Channel wear.")
H("880.d.6.D",3,"A technician lines up a soft top's frame, checks its hydraulic pump and aligns the latch pins so the top closes evenly. She is:","inspecting, removing, reinstalling and aligning convertible tops and related mechanisms",["painting","guessing","ignoring mechanisms"],"Convertible top.")
H("880.d.6.D",4,"If a convertible top does not seat evenly against the windshield header, the likely cause is:","misalignment of the frame or latches",["a full tank","clean glass","new wipers"],"Alignment issue.")
H("880.d.7.A",3,"A student reads the code stamped inside a bumper cover, such as PP or TPO, to determine the type of plastic. She is:","identifying the types of plastics used in automotive applications",["identifying paint","identifying glass","identifying tires"],"Plastic ID.")
H("880.d.7.A",4,"Stamped codes like >PP+EPDM< on a plastic part tell a technician:","the material, so the correct repair and adhesion method can be chosen",["the price","the paint color","the shop's address"],"Material codes.")
H("880.d.7.B",3,"A student washes a bumper cover with soap and water, then wipes it with a plastic-safe cleaner before sanding. She is:","cleaning and preparing the surface of plastic parts",["painting the part","gluing the part","ignoring prep"],"Clean plastic.")
H("880.d.7.B",4,"An adhesion promoter is sprayed on bare plastic to:","help primer and paint stick to the surface",["dry the plastic","remove color","cool the plastic"],"Promote adhesion.")
H("880.d.7.C",3,"A technician repairs a cracked flexible bumper cover using a plastic welder and reinforcing mesh. She is:","repairing rigid, semi-rigid or flexible plastic panels",["painting","guessing","ignoring cracks"],"Plastic repair.")
H("880.d.7.C",4,"For some plastics, a technician may choose adhesive repair instead of welding because:","the material may not weld well with heat",["heat always works","adhesives are weaker","welding is easier on every plastic"],"Match method to material.")
H("880.d.7.D",3,"A technician cuts out a damaged section of a fiberglass fender and feathers the edges for a repair patch. She is:","removing or repairing damaged areas from rigid exterior composite panels",["painting","guessing","avoiding repair"],"Composite repair.")
H("880.d.7.D",4,"When repairing fiberglass, a technician wears a respirator and gloves because dust and resin can:","irritate the lungs and skin",["help healing","cool the shop","clean the air"],"Protect yourself.")
H("880.d.7.E",3,"A technician removes a bonded composite door skin, cleans off old adhesive and installs a new skin with the specified adhesive, while aligning the supports. She is:","replacing bonded rigid exterior composite body panels, including straightening or aligning panel supports",["painting","guessing","ignoring supports"],"Replace composites.")
H("880.d.7.E",4,"After bonding a new composite panel, the technician should allow:","the adhesive to cure for the specified time before further work",["no cure time","water exposure at once","instant painting"],"Respect the cure.")
H("880.d.8.A",3,"Before the estimator can see all of the damage, a technician removes the bumper cover and the inner liner. She is:","preparing the vehicle for inspection by providing access to damaged areas",["washing the car","painting the car","ignoring damage"],"Provide access.")
H("880.d.8.A",4,"Providing access to hidden areas is important because it:","reveals damage not visible from the outside",["hides the damage","delays the estimate","adds paint"],"Hidden damage.")
H("880.d.8.B",3,"An estimator studies the points of impact and the direction of force to decide whether to pull, section or replace the rail. She is:","analyzing damage to determine the appropriate methods for overall repair",["guessing","ignoring damage","painting"],"Damage analysis.")
H("880.d.8.B",4,"The direction of impact matters in damage analysis because it:","shows how force traveled through the structure",["determines paint color","sets the tire size","picks the radio"],"Force path.")
H("880.d.8.C",3,"A technician looks over the rails, rocker panels and pillars for kinks, cracks and buckles. She is performing:","a visual inspection of structural components and members",["a paint job","a wash","an alignment"],"Structure inspection.")
H("880.d.8.C",4,"A kink in a frame rail indicates:","structural damage that must be repaired per the OEM procedure",["cosmetic damage only","a clean rail","a paint issue"],"Rails matter.")
H("880.d.8.D",3,"A technician mounts a vehicle on a measuring system and compares reference points to the manufacturer's data. She is:","identifying structural damage using measuring tools and equipment",["guessing","painting","ignoring data"],"Measure structure.")
H("880.d.8.D",4,"A measurement that differs from the specification by more than the allowed tolerance means:","the structure is out of position and needs correction",["the car is perfect","the paint is bad","the tires are worn"],"Tolerance check.")
H("880.d.8.E",3,"A technician inspects a fender, a hood and a door for dents, misaligned gaps and scratches. She is performing:","a visual inspection of non-structural components and members",["a weld","a wash","an alignment"],"Bolt-on panels.")
H("880.d.8.E",4,"Non-structural panels include parts that:","can be bolted or unbolted without altering the vehicle's frame",["hold the engine","form the frame","carry the crash load"],"Bolt-on.")
H("880.d.8.F",3,"After inspection, an estimator writes down which panels will be replaced, the materials they are made of and which procedures will be needed. She is determining:","the parts, components, material types and procedures necessary for a proper repair",["the paint color","the tire size","the customer's age"],"Repair plan.")
H("880.d.8.F",4,"If a damaged panel is aluminum, the estimator must plan for:","aluminum-specific tools and procedures",["steel tools only","no special plan","wood tools"],"Material-specific.")
H("880.d.8.G",3,"An estimator checks the paint for scratches, chips and fading and decides if the whole panel or only the damaged area needs refinishing. She is:","identifying the type and condition of the finish and determining if refinishing is required",["guessing","ignoring paint","polishing"],"Finish evaluation.")
H("880.d.8.G",4,"A color code on the vehicle's data plate is used to:","match the correct paint formula",["set tire pressure","choose a radio","set the oil type"],"Paint code.")
H("880.d.8.H",3,"A technician finds a bent control arm, a cracked headlight harness and a leaking radiator after a front-end collision. She is:","identifying suspension, electrical and mechanical component physical damage",["ignoring parts","painting","guessing"],"Mechanical damage.")
H("880.d.8.H",4,"A bent suspension part after a collision is dangerous because it can affect:","steering and alignment",["radio volume","paint color","seat comfort"],"Safety-critical.")
H("880.d.8.I",3,"A technician reviews a deployed airbag, a tensioned seat belt and a damaged impact sensor. She is:","identifying safety systems physical damage",["ignoring safety","painting","guessing"],"SRS damage.")
H("880.d.8.I",4,"After airbags have deployed, the technician should:","replace the deployed parts and related sensors per OEM procedures",["reuse the bags","tape them up","ignore them"],"Replace SRS.")
H("880.d.8.J",3,"An estimator notes a cracked dash pad, a torn seat and a damaged console after a collision. She is:","identifying interior component damage",["ignoring the interior","painting","guessing"],"Interior damage.")
H("880.d.8.J",4,"Interior damage is listed on an estimate so that it:","is repaired or replaced and billed correctly",["is ignored","is hidden","is painted over"],"Document the interior.")
H("880.d.8.K",3,"A technician notes that an aftermarket spoiler, a lift kit and a roof rack were damaged in the crash. She is:","identifying damage to add-on accessories and modifications",["ignoring accessories","painting","guessing"],"Aftermarket parts.")
H("880.d.8.K",4,"Aftermarket accessories damaged in a collision are listed separately because:","they may not be covered under the same policy",["they are always free","they add no cost","they cannot be repaired"],"Separate coverage.")
H("880.d.8.L",3,"A technician lists the structural bolts, torque-to-yield fasteners and airbag modules that cannot be reused after a collision. She is:","identifying single or one-time use components",["listing reusable tools","ignoring parts","painting"],"One-time use.")
H("880.d.8.L",4,"Torque-to-yield bolts should be replaced after removal because they:","stretch when tightened and cannot be reliably reused",["improve with reuse","are free","never wear"],"Stretch bolts.")
H("880.d.9.A",3,"A service writer records the owner's name, phone, insurance carrier and claim number at the start of a repair file. She is:","locating and recording customer and vehicle owner information",["ignoring the customer","painting","guessing"],"Customer data.")
H("880.d.9.A",4,"Customer information on an estimate must be handled with care because it is:","private and should be protected",["public","not needed","useless"],"Protect privacy.")
H("880.d.9.B",3,"An estimator reads the 17-character VIN on the dash to confirm country of origin, make, model and model year. She is:","locating and recording vehicle identification number information",["reading the odometer","reading a tire code","reading a paint code"],"VIN.")
H("880.d.9.B",4,"The tenth character of a VIN usually shows the vehicle's:","model year",["engine oil","owner's name","paint code"],"VIN position 10.")
H("880.d.9.C",3,"An estimator checks the trim level, the paint code and any installed accessories on the build sheet. She is:","identifying and recording vehicle options, including trim level, paint code, accessories and modifications",["ignoring options","painting","guessing"],"Options matter.")
H("880.d.9.C",4,"Trim level matters in estimating because it:","affects part numbers and pricing",["sets tire pressure","sets the radio","sets oil type"],"Price depends on trim.")
H("880.d.9.D",3,"An estimator notes that the vehicle has front, side and curtain airbags and a belt pretensioner, since they may need replacement. She is:","identifying the safety systems",["ignoring them","painting","guessing"],"Safety systems.")
H("880.d.9.D",4,"Airbag and restraint systems are noted on an estimate because they:","are critical to occupant safety and may need to be replaced",["add color","reduce cost","are optional"],"Note SRS.")
H("880.d.9.E",3,"An estimator knows that 'R&I' means remove and install, 'R&R' means remove and replace and 'O/H' means overhaul. She is applying:","appropriate estimating and parts terminology",["slang","guesswork","random words"],"Estimating terms.")
H("880.d.9.E",4,"On an estimate, 'R&R' next to a bumper cover means the part will be:","removed and replaced with a new or used part",["only repaired","only painted","only washed"],"R&R.")
H("880.d.9.F",3,"An estimator lists operations in a logical order: teardown, repair, replace, refinish, reassembly. She is:","determining and applying the appropriate estimating sequence",["guessing","ignoring order","painting first"],"Sequence.")
H("880.d.9.F",4,"Following an estimating sequence helps prevent:","missed operations and overlapping labor charges",["a complete estimate","accurate pricing","extra paperwork"],"Avoid missed items.")
H("880.d.9.G",3,"An estimator opens a procedure page in the estimating guide to see what operations are included in a fender replacement. She is:","utilizing estimating guide procedure pages",["ignoring the guide","painting","guessing"],"Procedure pages.")
H("880.d.9.G",4,"Procedure pages help an estimator avoid:","charging twice for tasks already included in a labor time",["accurate estimates","saving time","complete notes"],"Included operations.")
H("880.d.9.H",3,"An estimator uses a database to find the labor time to replace a quarter panel in hours. She is:","estimating labor time for operations",["guessing","ignoring time","painting"],"Labor time.")
H("880.d.9.H",4,"A labor time of 4.5 hours at $60 per hour comes to:","$270",["$64.50","$135","$450"],"4.5 × 60 = 270.")
H("880.d.9.I",3,"An estimator applies a higher rate for structural repair and a different rate for refinish work. She is:","selecting appropriate labor rates for each operation such as structural, non-structural, mechanical and refinish",["using one rate for all","guessing","ignoring rates"],"Different rates.")
H("880.d.9.I",4,"Structural repair often has a higher labor rate because it requires:","specialized equipment and training",["no tools","less time","no skills"],"Skill and equipment.")
H("880.d.9.J",3,"An estimator compares prices of OEM, aftermarket and recycled parts for a hood. She is:","selecting and pricing replacement parts such as OEM, alternative OEM, aftermarket and recycled",["ignoring prices","painting","guessing"],"Parts options.")
H("880.d.9.J",4,"A recycled (used) part is one that is:","taken from another vehicle in good condition",["brand new","made of paper","never installed"],"Recycled part.")
H("880.d.9.K",3,"An estimator adds charges for a pull-clamp setup and for masking a vehicle that aren't included in the guide's labor times. She is determining:","labor time, prices and charges for non-included operations and miscellaneous items",["included times","no extras","paint colors"],"Non-included.")
H("880.d.9.K",4,"Non-included operations are billed separately because they are:","additional work beyond the standard labor time",["part of the base time","free","not real"],"Not part of base time.")
H("880.d.9.L",3,"An estimator includes a hazardous waste disposal fee, shop supplies and an administrative fee on a repair order. She is:","determining additional material and charges such as environmental, administrative, shop and disposal fees",["ignoring fees","guessing","painting"],"Additional charges.")
H("880.d.9.L",4,"A hazardous waste fee is added to an estimate to cover:","the cost of properly disposing of paint and solvent waste",["a free gift","tire costs","the customer's coffee"],"Disposal costs.")
H("880.d.9.M",3,"An estimator multiplies the paint hours by a materials rate to price primer, base and clear. She is:","determining refinishing material and charges",["ignoring paint","guessing","washing"],"Paint materials.")
H("880.d.9.M",4,"Paint material charges are typically based on:","refinish labor hours times a materials rate",["the car's weight","the owner's age","the radio type"],"Materials rate.")
H("880.d.9.N",3,"Before giving an estimate to the customer, a writer proofreads it against the vehicle's damage notes and checks the math. She is:","reviewing computer-assisted and manually written estimates and verifying that the information is correct",["skipping review","guessing","ignoring errors"],"Verify the estimate.")
H("880.d.9.N",4,"A careful review of an estimate helps prevent:","errors that cost the shop or the customer money",["accuracy","trust","clarity"],"Errors cost.")
H("880.d.9.O",3,"An estimator adds time and material for applying seam sealer, cavity wax and weld-through primer on a repaired quarter panel. She is:","identifying labor time and material charges for restoring corrosion protection",["ignoring rust protection","painting","guessing"],"Corrosion protection charge.")
H("880.d.9.O",4,"Restoring corrosion protection after a structural repair is important to:","protect the repair from rust over time",["lower cost","shorten the repair","add noise"],"Rust prevention.")
H("880.d.9.P",3,"An estimator compares a $9,800 repair bill to a car's $8,500 market value to decide whether the vehicle is a total loss. She is:","determining the approximate vehicle retail value compared to the repair cost",["ignoring cost","guessing","painting"],"Total loss analysis.")
H("880.d.9.P",4,"A vehicle is generally considered a total loss when the repair cost:","exceeds a set percentage of the vehicle's value, as set by the insurer or state",["is very small","is zero","is under $50"],"Total loss threshold.")

B.balance()
B.save(os.path.join(os.path.dirname(os.path.abspath(__file__)), "..", "batches", "cte_131.jsonl"))
